package palindrome

import (
	"errors"
	"fmt"
	"strconv"
)

// Product represents a palindromic product and all its factorizations
// within the given range.
type Product struct {
	Product       int
	Factorizations [][2]int
}

// Products returns the smallest and largest palindromic products of two
// numbers in the inclusive range [fmin, fmax], along with all factor pairs
// for each.
func Products(fmin, fmax int) (Product, Product, error) {
	if fmin > fmax {
		return Product{}, Product{}, errors.New("fmin > fmax")
	}

	min := Product{-1, nil}
	max := Product{-1, nil}

	for i := fmin; i <= fmax; i++ {
		for j := i; j <= fmax; j++ {
			p := i * j
			if !isPalindrome(p) {
				continue
			}
			if min.Product < 0 || p < min.Product {
				min = Product{p, [][2]int{{i, j}}}
			} else if p == min.Product {
				min.Factorizations = append(min.Factorizations, [2]int{i, j})
			}
			if max.Product < 0 || p > max.Product {
				max = Product{p, [][2]int{{i, j}}}
			} else if p == max.Product {
				max.Factorizations = append(max.Factorizations, [2]int{i, j})
			}
		}
	}

	if min.Product < 0 {
		return Product{}, Product{}, errors.New("no palindromes")
	}

	return min, max, nil
}
```

